    color: l.paint['line-color'],
    weight: l.paint['line-width'],
    opacity: l.paint['line-opacity'],
    lineCap: l.layout['line-cap'],
    lineJoin: l.layout['line-join'],
    ...(l.paint['line-dasharray'] ? { dashArray: l.paint['line-dasharray'].map((d) => d * l.paint['line-width']).join(' ') } : {}),
