// ------------------------------------------------------------------ DOM markers

function el(className, html, { anchor = 'center', zIndex, title } = {}) {
  const node = document.createElement('div');
  node.className = `zy-map-marker ${className}`;
  node.innerHTML = html;
  node.dataset.anchor = anchor;
  if (zIndex != null) node.style.zIndex = String(zIndex);
  if (title) {
    node.title = title;
    node.setAttribute('aria-label', title);
  }
  return node;
}

const endpointShadowCss = () => {
  const sh = MAP.endpoint.shadow;
  return `drop-shadow(0 ${sh.y}px ${sh.blur}px ${rgba(sh.color, sh.opacity)})`;
};

/** Route start or end marker (RouteEndpointMarker). size: 22 (default) or tokens.endpoint.sizeCard (18). */
export function endpointMarker(kind, { size, title } = {}) {
  if (kind !== 'start' && kind !== 'end') throw new Error(`zyMap.endpointMarker: kind must be "start" or "end"`);
  const node = el(`zy-map-endpoint zy-map-endpoint--${kind}`, markerSvg(kind, { size }), { anchor: MAP.endpoint.anchor, zIndex: MAP.endpoint.zIndex, title });
  node.style.filter = endpointShadowCss();
  return node;
}

/** Planned stop: dark-green numbered badge. label: the stop number (optional). */
export function stopMarker(label, { title } = {}) {
  return el('zy-map-stop', markerSvg('stop', { label }), { zIndex: MAP.stop.zIndex, title });
}

/** Manual via-waypoint: white disc with a route-blue ring and index. */
export function waypointMarker(label, { title } = {}) {
  return el('zy-map-waypoint', markerSvg('waypoint', { label }), { zIndex: MAP.waypoint.zIndex, title });
}

